// Land mask for the world map: Natural Earth 110m (public domain) rasterised to a 144x52 grid
// covering latitudes 76 to -56. One bit per cell, row-major, most significant bit first, base64.

/**
 * @typedef {object} LandGrid
 * @property {number} cols
 * @property {number} rows
 * @property {number} lat0 latitude of the top edge
 * @property {number} lat1 latitude of the bottom edge
 * @property {string} b64 the bitmap
 */

/** @type {LandGrid} */
export const LAND = {
  cols: 144,
  rows: 52,
  lat0: 76,
  lat1: -56,
  b64: "",
};
